 "content": "def transform(grid):
    """Color alternating Chebyshev-distance bands around a 3-colored cross."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    cross_rows = [r for r in range(h) if all(v == 3 for v in grid[r])]
    cross_cols = [c for c in range(w) if all(grid[r][c] == 3 for r in range(h))]
    if len(cross_rows) != 1 or len(cross_cols) != 1:
        raise ValueError("expected exactly one full row and column of 3s")
    cr, cc = cross_rows[0], cross_cols[0]
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if r == cr or c == cc:
                out[r][c] = 3
            else:
                radius = max(abs(r - cr), abs(c - cc))
                out[r][c] = 4 if radius % 2 == 0 else 0
    return out
